-- ترحيل 128 — تصحيح قيم مزروعة خالفت النسخة الموقعة من لائحة تنظيم العمل (شهادة اعتماد 351743، 25-10-1446هـ).
-- لا جدول جديد ولا عمود جديد ولا قاعدة جديدة: القيم أدناه أخطأ فيها الاستخراج الآلي، والنص الموقع يقول غيرها.
-- الطريقة هي طريقة هذا المستودع في تصحيح صف مزروع بعد تطبيق ترحيله: يُسقط القادح الثابت، تُكتب القيمة،
-- ثم يعود القادح كما كان حرفًا بحرف (كما في الترحيل 113 مع leave_pay_effects_fixed)، ولا يُعدَّل ترحيل مطبَّق.

-- ————— 1) معدل الكيلومتر: م41 فقرة (ح) تنص عليه، ولا يتوقف على تعميم —————
-- ص p017 من النسخة الموقعة: «في حال عدم وجود سيارة خاصة للمنشأة وعدم وجود مطار بالمدينة المنتدب إليها العامل،
-- فإن المنشأة تصرف له ريالًا واحدًا عن الكيلو متر الواحد، وذلك من مقر المنشأة أو من أقرب مطار للمدينة المنتدب
-- إليها حتى وصوله للمدينة المنتدب إليها، ذهابًا وإيابًا».
-- وزُرعت نسخة اللائحة (regulation_art65) في الترحيل 112 بمعدل صفر، ووُضع المعدل في نسخة التعميم وحدها، فكان
-- تسجيل وضع الكيلومتر يُرفض بحجة أن «معدل م41 يسري مع التعميم» — وتلك نسبةٌ إلى التعميم لما نصت عليه اللائحة.
-- التصحيح: 100 هللة (ريال واحد) في القالب وفي نسخة كل كيان. قيم الدرجات والتقريب وتاريخ السريان والحالة كما هي،
-- فلا يتغير أي حساب قائم: الوضع الوحيد الذي يقرأ المعدل (mileage) كان مرفوضًا أصلًا فلا تذكرة مسجلة به.
DROP TRIGGER secondment_allowance_templates_fixed;
UPDATE secondment_allowance_templates
  SET mileage_rate_minor=100,
      body=body||' ومعدل الكيلومتر منصوص عليه في م41 فقرة (ح): ريال واحد عن الكيلو متر الواحد ذهابًا وإيابًا، حين لا سيارة للمنشأة ولا مطار في المدينة المنتدب إليها.'
  WHERE code='regulation_art65' AND mileage_rate_minor=0;
CREATE TRIGGER secondment_allowance_templates_fixed BEFORE UPDATE ON secondment_allowance_templates BEGIN SELECT RAISE(ABORT,'seed templates are fixed'); END;

DROP TRIGGER secondment_allowance_versions_fixed;
UPDATE secondment_allowance_versions
  SET mileage_rate_minor=100,
      body=body||' ومعدل الكيلومتر منصوص عليه في م41 فقرة (ح): ريال واحد عن الكيلو متر الواحد ذهابًا وإيابًا، حين لا سيارة للمنشأة ولا مطار في المدينة المنتدب إليها.',
      version=version+1
  WHERE code='regulation_art65' AND mileage_rate_minor=0;
-- القادح يعود كما كان في الترحيل 112 بلا حرف زائد ولا ناقص.
CREATE TRIGGER secondment_allowance_versions_fixed BEFORE UPDATE ON secondment_allowance_versions
WHEN NEW.version<>OLD.version+1 OR NEW.tenant_id<>OLD.tenant_id OR NEW.code<>OLD.code OR NEW.articles<>OLD.articles OR NEW.body<>OLD.body
  OR NEW.mileage_rate_minor<>OLD.mileage_rate_minor OR NEW.rounding<>OLD.rounding OR NEW.requires_attestation<>OLD.requires_attestation
  OR OLD.status='expired' OR (OLD.status='active' AND (NEW.status<>'expired' OR NEW.effective_from<>OLD.effective_from))
BEGIN SELECT RAISE(ABORT,'an allowance version is activated once and then only expires'); END;

-- ————— 2) نصّا مادتين في مكتبة السياسات يقرؤهما الموظف، وفيهما خطأ استخراج —————
-- المكتبة (الترحيل 110) زُرعت بـ127 مادة مستخرجة آليًا، وفي مادتين منها خطأ يغيّر المعنى لا الشكل:
--   م65 (ص 24): الجدول مزروع بعناوين أعمدته بلا أي من مبالغه الثمانية، فالموظف يقرأ «بدل انتداب خارج المملكة»
--     بلا رقم. الصفحة الموقعة تطبع خارج المملكة 2500 و1500 و900 و500، وداخلها 2100 و1000 و600 و400،
--     وتحتها «ملاحظة/ المبالغ المذكورة تصرف عن اليوم الواحد».
--   م76 (ص 28): نسبة الـ50% مقطوعة بين الفقرتين فتقرأ الجملة بلا معنى. الصفحة الموقعة تطبع: «تدفع المنشأة
--     للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا إليه (50%) من أجره الأساسي».
-- التصحيح يمشي في مسار المكتبة نفسه الذي يمشي فيه تحرير الموارد البشرية (curatorAction/edit_article):
-- نسخة جديدة برقم revision أعلى، ونصها محفوظ في policy_article_versions بملاحظة تقول سندها. والنسخة الأولى
-- (النص كما خرج من المستخرج) مزروعة أصلًا في الترحيل 110 ولا تُمس، فتعمل المقارنة سطرًا بسطر ويرى القارئ ما كان.
-- ثلاثة أشياء لا يغيّرها هذا الترحيل عمدًا: verification تبقى 'extracted' فيبقى وسم «مستخرج — يحتاج مطابقة
-- مع الأصل الموقّع» (المطابقة إقرار إنسان باسمه، لا فعل ترحيل)، وtitle_source تبقى كما هي (لا أحد هنا يعتمد
-- عنوانًا)، وedited_by فارغ لأن المحرر ليس شخصًا. أما وسم clause_reflow فيُرفع عن المادتين لأن النص الذي
-- يصفه لم يعد هو المخزون.
-- والقيد «revision=1» في كل جملة: إن كان أحد من الموارد البشرية قد حرَّر المادة بيده على القاعدة الحية قبل هذا
-- الترحيل، فلا يمر فوق تحريره — لا يفعل شيئًا، ويبقى التصحيح لمحرر بشري من الشاشة بالنصين نفسيهما.
-- policy-article-065
INSERT INTO policy_article_versions(id,article_id,tenant_id,revision,title,body,paragraphs,status,effective_from,note,edited_by,created_at)
  SELECT 'policy-article-065-rev2',id,tenant_id,revision+1,title,'تصرف المنشأة بدل الانتداب وفقًا للضوابط والفئات التالية:
جدول بدل الانتداب (الأعمدة كما طُبعت في الصفحة الموقعة من اليمين إلى اليسار): البدلات والمزايا | الرئيس التنفيذي | نواب الرئيس | مدراء العموم | للعاملين
بدل انتداب - لسفريات الاعمال - والتدريب - خارج المملكة | 2500 | 1500 | 900 | 500
بدل انتداب - لسفريات الاعمال - والتدريب - داخل المملكة | 2100 | 1000 | 600 | 400
ملاحظة/ المبالغ المذكورة تصرف عن اليوم الواحد.
1. يُصرف للعامل المنتدب داخل / خارج المملكة عن كل يوم فعلي يقضيه خارج مقر عمله، ويبدأ حساب هذا البدل من يوم الانتداب الفعلي الذي يُحدّد في قرار الانتداب، وينتهي بانتهاء مدته.
2. يخفض بدل الانتداب إلى الربع إذا وفرت المنشأة للعامل المنتدب السكن ووسيلة التنقل، أما إذا أمن له السكن فقط، فيخفض البدل إلى النصف، ولا يتأثر البدل في حال وفرت المنشأة له السكن مؤقتًا، أو حصوله على السكن ووسيلة التنقل من أية جهة غير المنشأة؛ ما لم تحتسب التكاليف على المنشأة.
3. يصرف للعامل المنتدب خارج المملكة تكاليف علاجه في حال عدم تغطية التأمين الصحي لهذا العلاج، على أن تؤخذ موافقة المنشأة على هذه التكاليف قبل البدء بها.
4. يصرف للعامل المنتدب داخل المملكة أو خارجها تذكرة إركاب بالطائرة ذهابًا وإيابًا.
5. في حال تطلب وصول العامل إلى جهة الانتداب مصاريف أخرى لازمة، فتتحملالمنشأة التعويض عنها بالإضافة إلى أي تكاليف رسوم أخرى تستوجب إنهاء المهمة، على سبيل المثال: رسوم إصدار تأشيرات السفر، الفحوصات الطبية، رسوم المطارات، تكاليف استئجار أماكن أداء المهمة، ولا يتم التعويض إلا بموجب الوثائق والمستندات الأصلية المثبتة لذلك، على أن يتم أخذ الموافقة عليها مبدئيا إلا في الحالات الطارئة.
6. يجوز تعويض العامل عن قيمة تذاكر السفر حسب الدرجة المخصصة له بموجب أحكام الإركاب الواردة في هذه اللائحة، وذلك في حال تم تكليف العامل المنتدب من مدير إدارة الموارد البشرية بتأمين وسيلة سفره.','[{"index":1,"marker":null,"text":"تصرف المنشأة بدل الانتداب وفقًا للضوابط والفئات التالية:"},{"index":2,"marker":null,"text":"جدول بدل الانتداب (الأعمدة كما طُبعت في الصفحة الموقعة من اليمين إلى اليسار): البدلات والمزايا | الرئيس التنفيذي | نواب الرئيس | مدراء العموم | للعاملين"},{"index":3,"marker":null,"text":"بدل انتداب - لسفريات الاعمال - والتدريب - خارج المملكة | 2500 | 1500 | 900 | 500"},{"index":4,"marker":null,"text":"بدل انتداب - لسفريات الاعمال - والتدريب - داخل المملكة | 2100 | 1000 | 600 | 400"},{"index":5,"marker":null,"text":"ملاحظة/ المبالغ المذكورة تصرف عن اليوم الواحد."},{"index":6,"marker":"1","text":"يُصرف للعامل المنتدب داخل / خارج المملكة عن كل يوم فعلي يقضيه خارج مقر عمله، ويبدأ حساب هذا البدل من يوم الانتداب الفعلي الذي يُحدّد في قرار الانتداب، وينتهي بانتهاء مدته."},{"index":7,"marker":"2","text":"يخفض بدل الانتداب إلى الربع إذا وفرت المنشأة للعامل المنتدب السكن ووسيلة التنقل، أما إذا أمن له السكن فقط، فيخفض البدل إلى النصف، ولا يتأثر البدل في حال وفرت المنشأة له السكن مؤقتًا، أو حصوله على السكن ووسيلة التنقل من أية جهة غير المنشأة؛ ما لم تحتسب التكاليف على المنشأة."},{"index":8,"marker":"3","text":"يصرف للعامل المنتدب خارج المملكة تكاليف علاجه في حال عدم تغطية التأمين الصحي لهذا العلاج، على أن تؤخذ موافقة المنشأة على هذه التكاليف قبل البدء بها."},{"index":9,"marker":"4","text":"يصرف للعامل المنتدب داخل المملكة أو خارجها تذكرة إركاب بالطائرة ذهابًا وإيابًا."},{"index":10,"marker":"5","text":"في حال تطلب وصول العامل إلى جهة الانتداب مصاريف أخرى لازمة، فتتحملالمنشأة التعويض عنها بالإضافة إلى أي تكاليف رسوم أخرى تستوجب إنهاء المهمة، على سبيل المثال: رسوم إصدار تأشيرات السفر، الفحوصات الطبية، رسوم المطارات، تكاليف استئجار أماكن أداء المهمة، ولا يتم التعويض إلا بموجب الوثائق والمستندات الأصلية المثبتة لذلك، على أن يتم أخذ الموافقة عليها مبدئيا إلا في الحالات الطارئة."},{"index":11,"marker":"6","text":"يجوز تعويض العامل عن قيمة تذاكر السفر حسب الدرجة المخصصة له بموجب أحكام الإركاب الواردة في هذه اللائحة، وذلك في حال تم تكليف العامل المنتدب من مدير إدارة الموارد البشرية بتأمين وسيلة سفره."}]',status,effective_from,'تصحيح بعد المطابقة مع الصفحة الموقعة ص 24: جدول م65 كان يحمل عناوين الأعمدة بلا أي من مبالغه الثمانية. أُعيدت المبالغ كما طُبعت (خارج المملكة 2500/1500/900/500، وداخلها 2100/1000/600/400) مع ملاحظة «المبالغ المذكورة تصرف عن اليوم الواحد»، وأُعيد ترتيب الفقرات الست إلى ترقيمها المطبوع. النص لم يُطابقه إنسان بعد، فوسم «مستخرج — يحتاج مطابقة مع الأصل الموقّع» باقٍ.',NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM policy_articles WHERE id='policy-article-065' AND revision=1;
