-- policy-article-076
INSERT INTO policy_article_versions(id,article_id,tenant_id,revision,title,body,paragraphs,status,effective_from,note,edited_by,created_at)
  SELECT 'policy-article-076-rev2',id,tenant_id,revision+1,title,'1. في حال تكليف العامل بالعمل الإضافي؛ يتم ذلك بموجب تكليف كتابي، أو الكتروني موجه له تصدره الجهة المسئولة في المنشأة يبين فيه عدد الساعات الإضافية المكلف بها العامل، وعدد الأيام اللازمة لذلك؛ وفق ما نصَّت عليه المادة (السادسة بعد المائة) من نظام العمل.
2. تدفع المنشأة للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا إليه (50%) من أجره الأساسي.','[{"index":1,"marker":"1","text":"في حال تكليف العامل بالعمل الإضافي؛ يتم ذلك بموجب تكليف كتابي، أو الكتروني موجه له تصدره الجهة المسئولة في المنشأة يبين فيه عدد الساعات الإضافية المكلف بها العامل، وعدد الأيام اللازمة لذلك؛ وفق ما نصَّت عليه المادة (السادسة بعد المائة) من نظام العمل."},{"index":2,"marker":"2","text":"تدفع المنشأة للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا إليه (50%) من أجره الأساسي."}]',status,effective_from,'تصحيح بعد المطابقة مع الصفحة الموقعة ص 28: نسبة الـ50% كانت مقطوعة بين الفقرتين («من% أجره الأساسي. (» في الأولى و«مضافًا (إليه 50» في الثانية) فتقرأ الجملة بلا معنى. أُعيدت الفقرة الثانية كما طُبعت: «تدفع المنشأة للعامل عن ساعات العمل الإضافية أجرا إضافيا يوازي أجر الساعة مضافًا إليه (50%) من أجره الأساسي». النص لم يُطابقه إنسان بعد، فوسم «مستخرج — يحتاج مطابقة مع الأصل الموقّع» باقٍ.',NULL,strftime('%Y-%m-%dT%H:%M:%fZ','now')
  FROM policy_articles WHERE id='policy-article-076' AND revision=1;
